ds_warns = _dirty_source_warnings(rels)
if ds_warns and not ALLOW_DIRTY_SOURCE:
    for _w in ds_warns:
        print(_w)
    print("[git] \u26d4 写前脏源检测未通过（fail-closed），提交已中止——"
          "本次 commit 会把他人在途 hunks 一并带走。逐 hunk 归属后再提交；"
          "确需放行加 --allow-dirty-source。")
    return
if ds_warns and ALLOW_DIRTY_SOURCE:
    for _w in ds_warns:
        print(_w)
    print("[git] \u26a0\ufe0f 已显式放行写前脏源告警（--allow-dirty-source）——本次计入留痕")
    _log_dirty_source_override(rels, desc)
